/**
 * Foreign IAP interface exposed to platforms that support async callbacks.
 *
 * Each method represents a high-level IAP operation that the rust core delegates to the host
 * platform.
 */
public protocol Iap: AnyObject, Sendable {
    
    /**
     * Gets products for the given product identifiers.
     *
     * # Errors
     *
     * Returns:
     *
     * - [`IapError::FetchProducts`] if the store failed to return products.
     * - [`IapError::StoreUnavailable`] if the platform store could not be reached.
     * - [`IapError::FfiError`] if the platform bridge failed unexpectedly.
     *
     * All platform specific errors should be converted into [`IapError`] before being returned to the
     * core.
     */
    func getProducts(ids: [ProductId]) async throws  -> [IapProduct]
    
    /**
     * Initiates a purchase for the provided arguments.
     *
     * # Errors
     *
     * Returns:
     *
     * - [`IapError::Purchase`] if the purchase failed.
     * - [`IapError::StoreUnavailable`] if the platform store could not be reached.
     * - [`IapError::FfiError`] if the platform bridge failed unexpectedly.
     *
     * All platform specific errors should be converted into [`IapError`] before being returned to the
     * core.
     */
    func purchase(arguments: PurchaseArguments) async throws  -> IapStatus
    
    /**
     * Acknowledges or finalizes a completed purchase.
     *
     * # Errors
     *
     * Returns:
     *
     * - [`IapError::Acknowledgement`] if the store failed to acknowledge the purchase.
     * - [`IapError::StoreUnavailable`] if the platform store could not be reached.
     * - [`IapError::FfiError`] if the platform bridge failed unexpectedly.
     *
     * All platform specific errors should be converted into [`IapError`] before being returned to the
     * core.
     */
    func acknowledge(orderId: UInt64) async throws 
    
}
