            return
        }

        try! rustCall { uniffi_payment_fn_free_time(handle, $0) }
    }

    

    
    /**
     * Suspends execution for the specified duration.
     */
open func delay(milliseconds: UInt64)async   {
    return
        try!  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_payment_fn_method_time_delay(
                    self.uniffiCloneHandle(),
                    FfiConverterUInt64.lower(milliseconds)
                )
            },
            pollFunc: ffi_payment_rust_future_poll_void,
            completeFunc: ffi_payment_rust_future_complete_void,
            freeFunc: ffi_payment_rust_future_free_void,
            liftFunc: { $0 },
            errorHandler: nil
            
        )
}
    

    
}



// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceTime {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceTime = UniffiVTableCallbackInterfaceTime(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeTime.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface Time: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTime.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface Time: handle missing in uniffiClone")
            }
        },
        delay: { (
            uniffiHandle: UInt64,
            milliseconds: UInt64,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteVoid,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> () in
                guard let uniffiObj = try? FfiConverterTypeTime.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return await uniffiObj.delay(
                     milliseconds: try FfiConverterUInt64.lift(milliseconds)
                )
            }

            let uniffiHandleSuccess = { (returnValue: ()) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultVoid(
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultVoid(
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsync(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceTime> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceTime>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitTime() {
    uniffi_payment_fn_init_callback_vtable_time(UniffiCallbackInterfaceTime.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTime: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<Time>()

    typealias FfiType = UInt64
    typealias SwiftType = Time

    public static func lift(_ handle: UInt64) throws -> Time {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return TimeImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: Time) -> UInt64 {
         if let rustImpl = value as? TimeImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Time {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Time, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


