/**
 * A monetary amount represented as a u64 and a decimal scale.
 * The numeric value is defined as:
 *
 * ```text
 * value = amount × 10^(-scale)
 * ```
 * ## Apple (`StoreKit`)
 *
 * `StoreKit` exposes prices as a Swift `Decimal`, which already represents the final user price for
 * the correct local currency.
 *
 * To convert to `Money`, the Swift layer:
 *
 * 1. Get the scale from your `Decimal`, you can do so by getting the abs value of `.exponent()`.
 * 2. Multiplies the `Decimal` value by `10^scale`
 * 4. Set that integer as `amount`
 *
 * **Example:*
 * `Decimal(4.55)` with `scale = 2` => `amount = 455`
 *
 * This ensures Rust receives the exact value without floating-point rounding.
 *
 * ## Android (Google Play Billing)
 *
 * Google Play Billing provides prices as `priceAmountMicros`, where `1_000_000 micros = 1
 * currency unit`.
 *
 * This corresponds to:
 *
 * - `scale = 6`
 * - `amount = priceAmountMicros`
 *
 * **Example:**
 * `€4.55` => `priceAmountMicros = 4_550_000`
 * `Money { amount: 4_550_000, scale: 6, currency: "EUR" }`
 */
public struct Money: Equatable, Hashable {
    public var amount: UInt64
    public var scale: UInt8
    public var currency: Currency
    public var formattedAmount: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(amount: UInt64, scale: UInt8, currency: Currency, formattedAmount: String) {
        self.amount = amount
