// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Payment telemetry events.
 */

public enum PaymentTelemetryEvent: Equatable, Hashable {
    
    /**
     * User tapped a purchasable product.
     *
     * Emitted before the Store purchase dialog is shown.
     */
    case purchaseProductTapped(flow: PaymentFlow, productId: String, offerId: String, activeSubscriptionProductIds: ActiveSubscriptionProductIds, 
        /**
         * Client-side timestamp in milliseconds.
         */occurredAtMs: Double
    )
    /**
     * Native store purchase was initiated.
     *
     * Emitted when IAP starts interacting with the Store.
     */
    case storePurchaseInitiated(userContext: UserContext, productId: String, 
        /**
         * Client-side timestamp in milliseconds.
         */occurredAtMs: Double
    )
    /**
     * Native store purchase interaction completed.
     *
     * Emitted after the Store returns a purchase result.
     */
    case storePurchaseCompleted(productId: String, storeInteractionResult: StoreInteractionResult
    )
    /**
     * Subscription management screen was presented to the user.
     */
    case subscriptionManagementViewed(
        /**
         * Client-side timestamp in milliseconds.
         */occurredAtMs: Double
    )
    /**
     * Subscription management screen finished loading.
     */
    case subscriptionManagementLoaded(activeSubscriptionProductIds: ActiveSubscriptionProductIds, loadedProductIds: LoadedProductIds, 
        /**
         * Client-side timestamp in milliseconds.
         */occurredAtMs: Double
    )





}

#if compiler(>=6)
extension PaymentTelemetryEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePaymentTelemetryEvent: FfiConverterRustBuffer {
    typealias SwiftType = PaymentTelemetryEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PaymentTelemetryEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .purchaseProductTapped(flow: try FfiConverterTypePaymentFlow.read(from: &buf), productId: try FfiConverterString.read(from: &buf), offerId: try FfiConverterString.read(from: &buf), activeSubscriptionProductIds: try FfiConverterTypeActiveSubscriptionProductIds.read(from: &buf), occurredAtMs: try FfiConverterDouble.read(from: &buf)
        )
        
        case 2: return .storePurchaseInitiated(userContext: try FfiConverterTypeUserContext.read(from: &buf), productId: try FfiConverterString.read(from: &buf), occurredAtMs: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .storePurchaseCompleted(productId: try FfiConverterString.read(from: &buf), storeInteractionResult: try FfiConverterTypeStoreInteractionResult.read(from: &buf)
        )
        
        case 4: return .subscriptionManagementViewed(occurredAtMs: try FfiConverterDouble.read(from: &buf)
        )
        
        case 5: return .subscriptionManagementLoaded(activeSubscriptionProductIds: try FfiConverterTypeActiveSubscriptionProductIds.read(from: &buf), loadedProductIds: try FfiConverterTypeLoadedProductIds.read(from: &buf), occurredAtMs: try FfiConverterDouble.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PaymentTelemetryEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .purchaseProductTapped(flow,productId,offerId,activeSubscriptionProductIds,occurredAtMs):
            writeInt(&buf, Int32(1))
            FfiConverterTypePaymentFlow.write(flow, into: &buf)
            FfiConverterString.write(productId, into: &buf)
            FfiConverterString.write(offerId, into: &buf)
            FfiConverterTypeActiveSubscriptionProductIds.write(activeSubscriptionProductIds, into: &buf)
            FfiConverterDouble.write(occurredAtMs, into: &buf)
            
        
        case let .storePurchaseInitiated(userContext,productId,occurredAtMs):
            writeInt(&buf, Int32(2))
            FfiConverterTypeUserContext.write(userContext, into: &buf)
            FfiConverterString.write(productId, into: &buf)
            FfiConverterDouble.write(occurredAtMs, into: &buf)
            
        
        case let .storePurchaseCompleted(productId,storeInteractionResult):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(productId, into: &buf)
            FfiConverterTypeStoreInteractionResult.write(storeInteractionResult, into: &buf)
            
        
        case let .subscriptionManagementViewed(occurredAtMs):
            writeInt(&buf, Int32(4))
            FfiConverterDouble.write(occurredAtMs, into: &buf)
            
        
        case let .subscriptionManagementLoaded(activeSubscriptionProductIds,loadedProductIds,occurredAtMs):
            writeInt(&buf, Int32(5))
            FfiConverterTypeActiveSubscriptionProductIds.write(activeSubscriptionProductIds, into: &buf)
            FfiConverterTypeLoadedProductIds.write(loadedProductIds, into: &buf)
            FfiConverterDouble.write(occurredAtMs, into: &buf)
            
        }
    }
}


