@_documentation(visibility: private)
#endif
public func FfiConverterTypePaymentTelemetryEvent_lift(_ buf: RustBuffer) throws -> PaymentTelemetryEvent {
    return try FfiConverterTypePaymentTelemetryEvent.lift(buf)
}

