        case 3: return .creatingNewSubscription
        
        case 4: return .acknowledging
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ReconcilingInFlightState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .postingToken:
